<?php require_once __DIR__.'/includes/permissions.php'; require_permission('residents.view'); $pdo=db();$u=current_user();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=post('action');try{if($a==='save' && (can('residents.create')||can('residents.edit'))){$id=(int)post('id',0);$fields=[trim((string)post('first_name')),trim((string)post('middle_name')),trim((string)post('last_name')),trim((string)post('suffix')),post('birth_date'),post('sex'),post('civil_status')?:null,trim((string)post('contact_number')),trim((string)post('email')),trim((string)post('address')),post('barangay'),trim((string)post('citizenship')),trim((string)post('occupation')),trim((string)post('emergency_contact')),trim((string)post('emergency_contact_number'))];if(!$fields[0]||!$fields[2]||!$fields[4]||!$fields[5]||!$fields[10])throw new Exception('Please complete required resident fields.');if($id){$q='UPDATE residents SET first_name=?,middle_name=?,last_name=?,suffix=?,birth_date=?,sex=?,civil_status=?,contact_number=?,email=?,address=?,barangay=?,citizenship=?,occupation=?,emergency_contact=?,emergency_contact_number=? WHERE id=?';$pdo->prepare($q)->execute([...$fields,$id]);audit('UPDATE','residents',$id,'Resident updated');}else{$pdo->beginTransaction();$pdo->prepare('INSERT INTO residents(patient_id,first_name,middle_name,last_name,suffix,birth_date,sex,civil_status,contact_number,email,address,barangay,citizenship,occupation,emergency_contact,emergency_contact_number,created_by) VALUES("PENDING",?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$fields,(int)$u['id']]);$id=(int)$pdo->lastInsertId();$pid='SR-'.date('Y').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE residents SET patient_id=? WHERE id=?')->execute([$pid,$id]);$pdo->commit();audit('CREATE','residents',$id,'Resident created');}flash('success','Resident saved successfully.');redirect(BASE_URL.'/residents.php');}elseif($a==='archive' && can('residents.delete')){$id=(int)post('id');$pdo->prepare('UPDATE residents SET status=IF(status="Active","Archived","Active") WHERE id=?')->execute([$id]);audit('ARCHIVE','residents',$id,'Resident archive status changed');flash('success','Resident status updated.');redirect(BASE_URL.'/residents.php');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$where=['1=1'];$params=[];$search=trim((string)get('search',''));$barangay=get('barangay','');$sex=get('sex','');$status=get('status','Active');if($search){$where[]='(patient_id LIKE ? OR first_name LIKE ? OR last_name LIKE ? OR contact_number LIKE ?)';$like="%$search%";array_push($params,$like,$like,$like,$like);}if($barangay){$where[]='barangay=?';$params[]=$barangay;}if($sex){$where[]='sex=?';$params[]=$sex;}if($status){$where[]='status=?';$params[]=$status;}$st=$pdo->prepare('SELECT * FROM residents WHERE '.implode(' AND ',$where).' ORDER BY last_name,first_name');$st->execute($params);$rows=$st->fetchAll();$barangays=all_barangays();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Residents</h1><p>Central resident and patient registry.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><div class="panel-head"><h5>Search & Filter</h5></div><form class="row g-2" method="get"><div class="col-md-4"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Patient ID, first name, last name, contact"></div><div class="col-md-3"><select name="barangay" class="form-select"><option value="">All Barangays</option><?php foreach($barangays as $b):?><option <?=$barangay===$b?'selected':''?>><?=e($b)?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="sex" class="form-select"><option value="">All Sex</option><option <?=$sex==='Male'?'selected':''?>>Male</option><option <?=$sex==='Female'?'selected':''?>>Female</option><option <?=$sex==='Other'?'selected':''?>>Other</option></select></div><div class="col-md-2"><select name="status" class="form-select"><option value="Active" <?=$status==='Active'?'selected':''?>>Active</option><option value="Archived" <?=$status==='Archived'?'selected':''?>>Archived</option><option value="" <?=$status===''?'selected':''?>>All Status</option></select></div><div class="col-md-1"><button class="btn btn-